import type { Screenshot } from '../config/site';

/** Width of the reduced versions generated by scripts/optimize_screenshots.py. */
const THUMB_WIDTH = 960;

/** Public URL of a screenshot stored in `public/screenshots/`, valid for any base path. */
export function screenshotUrl(file: string): string {
  return `${import.meta.env.BASE_URL}screenshots/${file}`;
}

/** `srcset` with the reduced and the full-resolution versions, so the browser picks the lightest suitable one. */
export function screenshotSrcSet(shot: Screenshot): string {
  return `${screenshotUrl(shot.thumb)} ${THUMB_WIDTH}w, ${screenshotUrl(shot.file)} ${shot.width}w`;
}
